---@meta
-- LuaLS definitions of the hyprdesk API (`hd.*`), alongside Hyprland's
-- (/usr/share/hypr/stubs/hl.meta.lua). Generated by `hyprdesk stubs`.

---@alias HD.Selector string|integer|(string|integer)[]
---@alias HD.Anchor "top-left"|"top"|"top-right"|"left"|"center"|"right"|"bottom-left"|"bottom"|"bottom-right"
---@alias HD.Color string # "#rrggbb", "#rrggbbaa", "rgb(rrggbb)", "rgba(rrggbbaa)"

---@class HD.ConfigSpec
---@field keys? { toggle?: string|false, launcher?: string|false, hide?: string|false, settings?: string|false, lock?: string|false, leave?: string|false, switch?: string|false, search?: string|false, search_desktop?: string|false, overview?: string|false, take?: string[]|false, media?: boolean }
---@field suspend_binds? boolean # desktop shown: suspend Hyprland's shortcuts
---@field clipboard_history? boolean # clipboard history: hyprdesk runs cliphist (":clip" in search)
---@field plugin_options? table<string, table<string, boolean|number|string>> # plugin options (Settings → Plugins → Configure), for every instance except options written on the instance
---@field update_commands? table<string, { check?: string, upgrade?: string }> # update commands per source (pacman, aur, apt, dnf, zypper, flatpak), as shell; empty: hyprdesk's own
---@field forced_modes? table<string, "no-desktop"|"launcher-only"|"full-desktop"> # forced mode: screen ("DP-1") or workspace ("ws:5"); no-desktop: never a desktop there; the others: the desktop switches to it on arrival
---@field autostart? boolean # launch XDG autostart applications (~/.config/autostart, /etc/xdg/autostart), once per session
---@field desktop_files? boolean # files of the Desktop folder (xdg-user-dir DESKTOP) and Trash as desktop icons
---@field float_launched? boolean # opened from the shown desktop: floating, centered window
---@field fx? table # Hyprland animations and effects: { ["decoration.blur.variant"] = 9, animations = { windowsIn = { speed = 4, curve = "spring", style = "popin" } } }
---@field lock_fingerprint? boolean # fingerprint (fprintd) besides the password, when a reader is present
---@field idle_manage? boolean # hyprdesk manages idle: writes the hypridle config and runs it
---@field idle_dim? integer # seconds of inactivity before dimming the screen (0: never)
---@field idle_lock? integer # seconds before locking (0: never)
---@field idle_dpms? integer # seconds before turning screens off (0: never)
---@field idle_suspend? integer # seconds before suspending (0: never)
---@field mode? "opaque"|"glass"
---@field fade_ms? integer
---@field transition? "fade"|"slide"|"none"
---@field crossfade_ms? integer
---@field running_apps? "off"|"workspace"|"all"
---@field show_on? "all"|"focused"|"primary"
---@field apps_style? "auto"|"plein"|"central" # application launcher: large sheet in full-desktop and centered card otherwise (auto), or always one of them
---@field apps_suggestions? integer # most launched applications highlighted (0 to 16, 8 by default)
---@field apps_categories? boolean # categories in the large sheet
---@field apps_unified? boolean # the same launcher in every mode (keys.search taken from hyprland.lua); false: hyprland.lua's one outside the full desktop
---@field launcher_group? "none"|"app"|"workspace" # launcher: one entry per window, per application, or per workspace
---@field primary? string|false # primary screen (connector, e.g. "DP-1"): anchored at 0×0, desktop/bar/settings
---@field close_on_launch? boolean
---@field icon_scope? "global"|"screen"|"workspace"
---@field icon_double_click? boolean
---@field icon_theme? string
---@field font? string # "Mindlog" by default (embedded), or an installed family
---@field font_size? number
---@field advanced_settings? boolean Settings screen: all the details (otherwise the essentials)
---@field tour_seen? boolean Guided tour done or dismissed (no longer offered)
---@field language? "auto"|"fr"|"en" Interface language (auto: the system's)
---@field layout? string Default layout: "dwindle", "master", "scrolling", "monocle", "grid", "columns", "rows", "centered" or "lua:<name>"
---@field layout_workspaces? table<string|integer, string> Layout of some workspaces ({ [3] = "monocle" })
---@field dwindle? table<string, boolean|number> Dwindle options (preserve_split, smart_split, force_split, default_split_ratio…)
---@field master? table<string, boolean|number|string> Master options (orientation, mfact, new_status, new_on_top…)
---@field scrolling? table<string, boolean|number|string> Scrolling options (direction, column_width, follow_focus…)
---@field terminal? string # "kitty" → "kitty -e <cmd>"; or a "foot {cmd}" template
---@field glass_opacity? number # 0..1
---@field background? HD.Color
---@field workspace_monitors? table<string, (string|integer)[]> # screen (or "primary") → workspaces; the first one is shown by default
---@field workspaces? integer|false # permanent workspaces 1..N (1 to 30); false: left to Hyprland
---@field grid? { cell?: integer, gap?: integer, margin?: integer, icon_size?: integer }
---@field theme? HD.Theme

---@class HD.Effect
---@field opacity? number # 0..1: background opacity
---@field blur? boolean # blur of what lies behind (not for widgets)

---@class HD.Theme
---@field name? string
---@field fg? HD.Color # text
---@field bg? HD.Color # surfaces
---@field accent? HD.Color
---@field effects? { bar?: HD.Effect, menus?: HD.Effect, launcher?: HD.Effect, settings?: HD.Effect, widgets?: HD.Effect }

---@class HD.RuleSpec
---@field workspace? HD.Selector # "*" = all
---@field monitor? HD.Selector

---@class HD.WallpaperSpec: HD.RuleSpec
---@field path? string
---@field rotate? { dir: string, interval?: number, shuffle?: boolean }
---@field color? HD.Color
---@field fit? "cover"|"contain"|"fill"|"center"
---@field span? boolean|"lock"|"desktop" # one scene across all screens, cut according to their layout; "lock": on the lock screen only (not with color)

---@class HD.DesktopSpec: HD.RuleSpec
---@field mode? "opaque"|"glass"
---@field inherit? boolean # false: ignore global icons and widgets

---@class HD.IconSpec: HD.RuleSpec
---@field id? string
---@field label? string
---@field app? string # .desktop identifier
---@field path? string
---@field exec? string
---@field terminal? boolean
---@field icon? string # theme icon name or image path
---@field pos? integer[] # { column, row }, starting from 0

---@class HD.WidgetSpec: HD.RuleSpec
---@field id? string
---@field anchor? HD.Anchor
---@field x? number
---@field y? number
---@field size? number
---@field interval? number # seconds
---@field card? boolean
---@field format? string # clock: strftime
---@field show? string[] # system: "cpu", "ram", "load", "uptime", "disk:<mount point>"
---@field player? string # media: substring of the MPRIS name, "*" = all
---@field exec? string # command
---@field timeout? number # command, seconds
---@field render? fun(): string|number|HD.Rendered # lua
---@field on_click? fun()
---@field on_scroll? fun(direction: integer) # -1 or +1
---@field menu? fun(): (HD.MenuItem|string)[]

---@class HD.Rendered
---@field text? string
---@field icon? string
---@field tooltip? string
---@field state? "normal"|"active"|"warning"|"critical"|"hidden"

---@class HD.MenuItem
---@field label? string
---@field detail? string
---@field icon? string
---@field checked? boolean
---@field disabled? boolean
---@field action? fun()
---@field confirm? string
---@field header? string

---@class HD.HookEvent
---@field event "show"|"hide"|"workspace"
---@field monitor string
---@field workspace string

---@class HD.API
---@field version string
---@field exe string Path of the running hyprdesk (e.g. hd.spawn(hd.exe .. " lock")).
hd = {}

---@param spec HD.ConfigSpec
function hd.config(spec) end

---@param spec HD.WallpaperSpec
function hd.wallpaper(spec) end

---@param spec HD.DesktopSpec
function hd.desktop(spec) end

---@class HD.AssignSpec
---@field app? string # .desktop identifier (window class inferred)
---@field class? string # or a class regular expression, for Hyprland
---@field workspace string|integer
---@field silent? boolean # open over there without taking the user along

--- An application's windows open on a workspace.
---@param spec HD.AssignSpec
function hd.assign(spec) end

---@param spec HD.IconSpec
function hd.icon(spec) end

---@param kind "clock"|"calendar"|"system"|"media"|"command"|"lua"|string # or a plugin name
---@param spec? HD.WidgetSpec
function hd.widget(kind, spec) end

--- Repositions a widget by its id (`clock#0` for the first `hd.widget("clock")`).
---@param id string
---@param spec { anchor?: HD.Anchor, x?: number, y?: number, size?: number, card?: boolean }
function hd.place(id, spec) end

--- Removes a widget by its id (written by the Settings screen when a widget from hyprdesk.lua is turned off).
---@param id string
function hd.disable(id) end

---@param event "show"|"hide"|"workspace"
---@param fn fun(e: HD.HookEvent)
function hd.on(event, fn) end

---@alias HD.BarModule "workspaces"|"window"|"volume"|"brightness"|"tray"|"desktop"|string|table # or a widget: "clock", { "clock", format = "%H:%M" }

---@class HD.BarSpec
---@field monitor? HD.Selector # "primary": the primary screen
---@field compact? "auto"|"always"|"never" # auto: screens narrower than 1600 px, or vertical ones
---@field portrait? { left?: table, center?: table, right?: table } # modules for vertical screens
---@field position? "top"|"bottom"
---@field height? integer
---@field left? HD.BarModule[]
---@field center? HD.BarModule[]
---@field right? HD.BarModule[]

--- hyprdesk's native bar; `false` removes it.
---@param spec HD.BarSpec|false
function hd.bar(spec) end

--- Session component launched and supervised by hyprdesk.
---@param name string
---@param spec { exec: string, restart?: boolean }
function hd.component(name, spec) end

---@class HD.Rendered
---@field text? string
---@field icon? string # theme icon name ("…-symbolic": tinted) or path
---@field tooltip? string
---@field state? "normal"|"active"|"warning"|"critical"|"hidden"

---@class HD.MenuEntry
---@field header? string # section title
---@field label? string
---@field detail? string
---@field icon? string
---@field checked? boolean
---@field disabled? boolean
---@field confirm? string # confirmation question before the action
---@field input? string # text field (placeholder): Enter calls action(text)
---@field image? string # local image (path or file:///…), an album cover for instance
---@field secret? boolean # masked input (password)
---@field action? fun(text?: string)

---@class HD.Plugin
---@field name? string
---@field description? string
---@field interval? number
---@field anchor? HD.Anchor
---@field options? table<string, any>
---@field render fun(o: table): string|HD.Rendered
---@field on_click? fun(o: table)
---@field on_scroll? fun(o: table, dir: integer)
---@field menu? fun(o: table): (HD.MenuEntry|"-")[]

--- Launches a program without waiting (through Hyprland).
---@param cmd string
function hd.spawn(cmd) end

--- Runs a shell command and returns its standard output.
---@param cmd string
---@return string
function hd.exec(cmd) end

--- Launches a command through Hyprland, without waiting for its output.
---@param cmd string
function hd.spawn(cmd) end

--- Text in the interface language: the French text is the key in
--- hyprdesk's catalog (locales/en.toml); if missing, it is returned as is.
---@param text string
---@return string
function hd.t(text) end

--- Interface language: "fr" or "en" (for plugins that ship their own texts).
---@return "fr"|"en"
function hd.lang() end
